style:
.bglc{position:relative;border:1px solid var(--border-color);border-radius:18px;overflow:hidden;
  margin:4px 0 18px;background:var(--card-bg);box-shadow:inset 0 2px 0 rgba(241,7,48,.5)}
[data-theme=dark] .bglc{background:radial-gradient(900px 420px at 75% -20%,#1d2941 0%,#15151a 62%)}
.bglc-sky{display:block}
[data-theme=dark] .bglc-sky{position:absolute;inset:0;width:100%;height:100%}
.bglc-hero{position:relative;z-index:2;padding:10px 170px 6px 28px}
@media(max-width:800px){.bglc-hero{padding-right:28px}}
[data-theme=dark] .bglc-hero{padding-top:26px}
.bglc-greet{display:flex;align-items:center;gap:9px;color:var(--text-muted);font-size:13px}
.bglc-h1{font-family:'Space Grotesk','Inter',sans-serif;font-size:clamp(20px,2.6vw,27px);
  margin:6px 0 2px;letter-spacing:-.015em;font-weight:700;color:var(--heading-color)}
.bglc-h1 b{color:#f0a04b}
.bglc-sub{color:var(--text-muted);margin:0;font-size:13.5px}
.bglc-month{position:absolute;top:20px;right:26px;z-index:3;text-align:right}
.bglc-month .m{font-family:'Space Grotesk',sans-serif;font-size:22px;font-weight:700;letter-spacing:.04em;color:var(--heading-color)}
.bglc-month .y{font-size:11.5px;color:var(--text-muted);letter-spacing:.3em}
.bglc-verdict{display:inline-flex;align-items:center;gap:8px;margin-top:8px;font-size:11.5px;font-weight:800;
  padding:4px 12px;border-radius:100px}
.bglc-verdict.no{color:#e8776b;background:rgba(232,119,107,.1);border:1px solid rgba(232,119,107,.35)}
.bglc-verdict.ok{color:#2fb56f;background:rgba(47,181,111,.1);border:1px solid rgba(47,181,111,.35)}
.bglc-rail{position:relative;z-index:2;display:grid;grid-template-columns:repeat(5,1fr);gap:11px;padding:10px 28px 24px}
@media(max-width:900px){.bglc-rail{grid-template-columns:1fr 1fr}.bglc-line{display:none}}
.bglc-line{position:absolute;left:40px;right:40px;top:50%;height:1.5px;z-index:0;background:var(--border-color)}
.bglc-stg{position:relative;z-index:2;background:var(--card-bg);border:1px solid var(--border-color);
  border-radius:14px;padding:13px 13px 11px;cursor:pointer;text-decoration:none;color:inherit;display:block;
  transition:transform .15s,border-color .15s}
[data-theme=dark] .bglc-stg{background:linear-gradient(180deg,#1b1b21,#15151a);box-shadow:inset 0 1px 0 rgba(255,255,255,.05)}
.bglc-stg:hover{transform:translateY(-3px);border-color:#f0a04b;text-decoration:none}
.bglc-stg .n{display:inline-grid;place-items:center;width:25px;height:25px;border-radius:50%;
  font-weight:800;font-size:12px;margin-bottom:8px}
.bglc-stg.done .n{background:rgba(47,181,111,.15);color:#2fb56f;border:1.5px solid #2fb56f}
.bglc-stg.now .n{background:#f0a04b;color:#191203;border:1.5px solid #f0a04b;width:29px;height:29px;box-shadow:0 0 14px rgba(240,160,75,.5)}
.bglc-stg.wait .n{background:transparent;color:var(--text-muted);border:1.5px solid var(--border-color)}
.bglc-stg b{display:block;font-family:'Space Grotesk','Inter',sans-serif;font-size:13px;line-height:1.3;color:var(--heading-color)}
.bglc-stg span{display:block;font-size:11px;color:var(--text-muted);margin-top:3px;line-height:1.4}
.bglc-stg.done b{color:#2fb56f}
.bglc-stg.now{border:2px solid #f0a04b;transform:scale(1.05);z-index:3;animation:bglcbreathe 2.2s ease-in-out infinite}
.bglc-stg.now b{color:#f0a04b;font-size:14px}
.bglc-stg.now:hover{transform:scale(1.05) translateY(-3px)}
@keyframes bglcbreathe{0%,100%{box-shadow:0 0 16px rgba(240,160,75,.18)}50%{box-shadow:0 0 30px rgba(240,160,75,.4)}}
.bglc-stg.now::after{content:"DO THIS NEXT";position:absolute;top:-9px;right:9px;font-size:8.5px;
  font-weight:800;letter-spacing:.12em;background:#f0a04b;color:#191203;padding:2px 8px;border-radius:100px}
.bglc-stg .st{position:absolute;top:11px;right:11px;font-size:10px;font-weight:800}
.bglc-stg.done .st{color:#2fb56f}.bglc-stg.now .st{color:#f0a04b}.bglc-stg.wait .st{color:var(--text-muted)}
.bglc-foot{position:relative;z-index:2;padding:0 28px 12px;font-size:10.5px;color:var(--text-muted)}
.bglc-help{position:relative;z-index:2;padding:0 28px 14px}
.bglc-help-t{font-size:10.5px;letter-spacing:.16em;text-transform:uppercase;color:var(--text-muted);font-weight:800;margin-bottom:8px}
.bglc-help details{border:1px solid var(--border-color);border-radius:11px;margin-bottom:7px;background:var(--card-bg)}
[data-theme=dark] .bglc-help details{background:linear-gradient(180deg,#1b1b21,#15151a)}
.bglc-help summary{cursor:pointer;padding:10px 15px;font-size:12.5px;font-weight:700;
  font-family:'Space Grotesk','Inter',sans-serif;color:var(--heading-color);list-style-position:inside}
.bglc-help summary:hover{color:#f0a04b}
.bglc-help details p{padding:0 15px 12px;margin:0;font-size:12.5px;color:var(--text-muted);line-height:1.6}
.bglc-guide{display:inline-block;margin-top:4px;font-size:12.5px;font-weight:700;color:#f0a04b !important;text-decoration:none !important}
.bglc-rail{position:relative}
.bglc-line{position:absolute;left:38px;right:38px;top:50%;height:2px;z-index:0;border-radius:2px}
.bglc-line .spark{position:absolute;top:-3px;width:8px;height:8px;border-radius:50%;
  background:#f0a04b;box-shadow:0 0 12px 3px rgba(240,160,75,.7);
  animation:bglcspark 3.5s linear infinite}
@keyframes bglcspark{0%{left:0%}100%{left:100%}}
@media(max-width:900px){.bglc-line{display:none}}

script:
(function(root){
  root = root_element || document.getElementById('bglc-root');
  if(!root) return;
  var MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  var now=new Date(), ym=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
  root.querySelector('.bglc-month .m').textContent=MONTHS[now.getMonth()].toUpperCase();
  root.querySelector('.bglc-month .y').textContent=now.getFullYear();
  var first=(frappe.boot.user_info && frappe.boot.user_info[frappe.session.user] ?
    (frappe.boot.user_info[frappe.session.user].fullname||'').split(' ')[0] : '');
  var h=now.getHours(), part=h<12?'Good morning':(h<17?'Good afternoon':'Good evening');
  var days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  root.querySelector('.bglc-greet').textContent=days[now.getDay()]+' '+now.getDate()+' '+MONTHS[now.getMonth()]+' - Airport + Tema';

  function isDark(){
    var t=document.documentElement.getAttribute('data-theme');
    if(t) return t==='dark';
    return window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches;
  }

  // ---- constellation: full-sky dark / corner-block light, twinkling ----
  var cv=root.querySelector('.bglc-sky'), cx=cv.getContext('2d'), pts=[], W, H;
  var DARKC=['240,160,75','63,193,203','154,150,232'];
  var LIGHTC=['194,97,12','13,111,119','91,83,168'];
  function setup(){
    pts=[];
    if(isDark()){ W=cv.width=root.offsetWidth; H=cv.height=Math.max(root.offsetHeight,220);
      cv.style.position='absolute'; cv.style.inset='0'; cv.style.width='100%'; cv.style.height='100%'; cv.style.margin='0';
      for(var i=0;i<40;i++) pts.push(mk(Math.random()*W,Math.random()*H,DARKC[i%3]));
    } else { W=cv.width=340; H=cv.height=150;
      cv.style.position='static'; cv.style.width='340px'; cv.style.height='150px'; cv.style.margin='6px 0 0 12px';
      for(var i=0;i<13;i++) pts.push(mk(Math.random()*W,Math.random()*H,LIGHTC[i%3]));
    }
  }
  function mk(x,y,c){ return {x:x,y:y,vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,
    c:c,r:Math.random()*1.6+.6,ph:Math.random()*6.283,tw:.8+Math.random()*1.8}; }
  var lastTheme=null, lastW=0;
  function tick(){
    var t=isDark();
    var rw=root.offsetWidth||0;
    if(t!==lastTheme || (t && rw>0 && Math.abs(rw-lastW)>4)){ lastTheme=t; lastW=rw; setup(); }
    cx.clearRect(0,0,W,H);
    pts.forEach(function(p){
      p.x+=p.vx; p.y+=p.vy;
      if(p.x<0||p.x>W)p.vx*=-1; if(p.y<0||p.y>H)p.vy*=-1;
      var tk=.2+.8*(.5+.5*Math.sin(performance.now()/1000*p.tw+p.ph));
      cx.beginPath(); cx.arc(p.x,p.y,p.r*(0.75+0.45*tk),0,6.283);
      cx.fillStyle='rgba('+p.c+','+(0.9*tk).toFixed(3)+')'; cx.fill();
    });
    for(var i=0;i<pts.length;i++)for(var j=i+1;j<pts.length;j++){
      var a=pts[i],b=pts[j],d=Math.hypot(a.x-b.x,a.y-b.y);
      if(d<110){ cx.beginPath(); cx.moveTo(a.x,a.y); cx.lineTo(b.x,b.y);
        cx.strokeStyle='rgba('+a.c+','+((t?0.16:0.24)*(1-d/110)).toFixed(3)+')'; cx.lineWidth=1; cx.stroke(); }
    }
    requestAnimationFrame(tick);
  }
  tick();

  // ---- readiness -> five stones ----
  frappe.call({ method:'bgl_ops.api.payroll_readiness', args:{month:ym} }).then(function(r){
    var d=r.message||{}, L={};
    (d.lines||[]).forEach(function(l){ L[l.key]=l; });
    root.querySelector('.bglc-ver').textContent='v'+(d.app_version||'');
    function agg(keys){
      var ok=true, warn=true, det=[];
      keys.forEach(function(k){ var l=L[k]; if(!l) return;
        if(!l.ok && !l.warn) ok=false;
        if(!l.warn) warn=false;
        if(!l.ok) det.push(l.detail); });
      return {ok:ok, det:det.join(' | ')};
    }
    var stones=[
      {t:'Trip sheets', a:agg(['sheet_airport','sheet_tema']), link:'/app/trip-log-sheet', d:'Airport + Tema entered and locked'},
      {t:'Trip earnings', a:agg(['earnings']), link:'/app/trip-log-sheet', d:'Generated from the locked sheets'},
      {t:'Payroll Prep Sheet', a:agg(['hires','doj','deductions','allowances']), link:'/app/deduction-sheet', d:'Hires, loans, advances, absences, allowances'},
      {t:'Review drafts', a:agg(['foreign','review']), link:'/app/review-board', d:'Approve every draft; leavers flagged'},
      {t:'Payroll Entry', a:{ok:!!d.ready, det:''}, link:'/app/payroll-entry/new', d:'Run it when all stones are green'}
    ];
    var doneCount=0, nowSet=false, rail=root.querySelector('.bglc-rail');
    var lineEl=document.createElement('div');
    lineEl.className='bglc-line';
    lineEl.innerHTML='<span class="spark"></span>';
    rail.appendChild(lineEl);
    stones.forEach(function(st,i){
      var cls; 
      if(st.a.ok){ cls='done'; doneCount++; }
      else if(!nowSet){ cls='now'; nowSet=true; }
      else cls='wait';
      var el=document.createElement('a');
      el.className='bglc-stg '+cls; el.href=st.link;
      el.innerHTML='<span class="st">'+(cls==='done'?'DONE':(cls==='now'?'OPEN':'WAITING'))+'</span>'+
        '<span class="n">'+(cls==='done'?'&#10003;':(i+1))+'</span>'+
        '<b>'+st.t+'</b><span>'+((cls!=='done'&&st.a.det)?st.a.det:st.d)+'</span>';
      rail.appendChild(el);
    });
    var p1=(doneCount/5)*100, p2=(Math.min(doneCount+1,5)/5)*100;
    lineEl.style.background='linear-gradient(90deg,#2fb56f 0 '+p1+'%,#f0a04b '+p1+'% '+p2+'%,var(--border-color) '+p2+'%)';
    root.querySelector('.bglc-h1').innerHTML=part+(first?', '+first:'')+' - <b>'+
      MONTHS[now.getMonth()]+' payroll is '+doneCount+' of 5 steps done.</b>';
    var v=root.querySelector('.bglc-verdict');
    if(d.ready){ v.className='bglc-verdict ok'; v.textContent='READY FOR PAYROLL ENTRY'; }
    else { v.className='bglc-verdict no'; v.textContent='NOT READY - '+(5-doneCount)+' step(s) remain'; }
  });
})(typeof root_element !== 'undefined' ? root_element : null);

