script:
(function(root){
  root = root_element || document.getElementById('bgle-root');
  if(!root) return;
  var MONTHS=['January','February','March','April','May','June','July','August','September','October','November','December'];
  var now=new Date(), ym=now.getFullYear()+'-'+String(now.getMonth()+1).padStart(2,'0');
  var first=(frappe.boot.user_info && frappe.boot.user_info[frappe.session.user] ?
    (frappe.boot.user_info[frappe.session.user].fullname||'').split(' ')[0] : '');
  var h=now.getHours(), part=h<12?'Good morning':(h<17?'Good afternoon':'Good evening');
  var days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
  root.querySelector('.bgle-greet').textContent=days[now.getDay()]+' '+now.getDate()+' '+MONTHS[now.getMonth()]+' '+now.getFullYear();
  root.querySelector('.bgle-h1').innerHTML=part+(first?', '+first:'')+' - <b>here is Betonsa at a glance.</b>';

  var cv=root.querySelector('.bgle-sky'), cx=cv.getContext('2d'), pts=[], W, H;
  function dark(){
    var t=document.documentElement.getAttribute('data-theme');
    if(t) return t==='dark';
    return window.matchMedia && matchMedia('(prefers-color-scheme: dark)').matches;
  }
  var lastW=0;
  function size(){ W=cv.width=root.offsetWidth||800; H=cv.height=Math.max(root.offsetHeight,220); lastW=root.offsetWidth||0; }
  size(); window.addEventListener('resize', size);
  var CD=['240,160,75','63,193,203','154,150,232'], CL=['194,97,12','13,111,119','91,83,168'];
  for(var i=0;i<34;i++) pts.push({x:Math.random()*1400,y:Math.random()*460,
    vx:(Math.random()-.5)*.25,vy:(Math.random()-.5)*.25,i3:i%3,r:Math.random()*1.6+.6,
    ph:Math.random()*6.283,tw:.8+Math.random()*1.8});
  (function tick(){
    var rw=root.offsetWidth||0;
    if(rw>0 && Math.abs(rw-lastW)>4) size();
    var C=dark()?CD:CL, la=dark()?0.16:0.2, da=dark()?0.9:0.8;
    cx.clearRect(0,0,W,H);
    pts.forEach(function(p){
      p.x+=p.vx; p.y+=p.vy;
      if(p.x<0||p.x>W)p.vx*=-1; if(p.y<0||p.y>H)p.vy*=-1;
      var tk=.2+.8*(.5+.5*Math.sin(performance.now()/1000*p.tw+p.ph));
      cx.beginPath(); cx.arc(p.x,p.y,p.r*(0.75+0.45*tk),0,6.283);
      cx.fillStyle='rgba('+C[p.i3]+','+(da*tk).toFixed(3)+')'; cx.fill();
    });
    for(var i=0;i<pts.length;i++)for(var j=i+1;j<pts.length;j++){
      var a=pts[i],b=pts[j],d=Math.hypot(a.x-b.x,a.y-b.y);
      if(d<110){ cx.beginPath(); cx.moveTo(a.x,a.y); cx.lineTo(b.x,b.y);
        cx.strokeStyle='rgba('+C[a.i3]+','+(la*(1-d/110)).toFixed(3)+')'; cx.lineWidth=1; cx.stroke(); }
    }
    requestAnimationFrame(tick);
  })();

  frappe.call({method:'bgl_ops.api.dashboard_data'}).then(function(r){
    var d=r.message||{};
    var yq=0, ya=0;
    (d.yesterday_by_site||[]).forEach(function(y){ yq+=(+y.qty||0); ya+=(+y.amt||0); });
    root.querySelector('#bgle-yday').textContent=yq? (yq+' qty / GHS '+Math.round(ya).toLocaleString()) : 'no logs';
    var cost=(+((d.trips_month||{}).amt)||0)+(+((d.cubic_month||{}).amt)||0);
    root.querySelector('#bgle-cost').textContent=Math.round(cost).toLocaleString();
  });
  frappe.call({method:'bgl_ops.api.payroll_readiness', args:{month:ym}}).then(function(r){
    var d=r.message||{};
    root.querySelector('#bgle-ready').textContent=d.ready?'READY':'IN PROGRESS';
    root.querySelector('#bgle-ready').style.color=d.ready?'#2fb56f':'#f0a04b';
    var names={sheet_airport:'Sheet Airport',sheet_tema:'Sheet Tema',earnings:'Earnings',
      hires:'New hires',deductions:'Deductions',allowances:'Allowances',review:'Review'};
    var rail=root.querySelector('.bgle-rail'), shown=0;
    (d.lines||[]).forEach(function(l){
      if(!names[l.key]||shown>=5) return; shown++;
      var el=document.createElement('div');
      el.className='bgle-stone '+(l.ok?'ok':'no');
      el.innerHTML='<b>'+(l.ok?'&#10003; ':'')+names[l.key]+'</b><span>'+l.detail+'</span>';
      rail.appendChild(el);
    });
  });
})(typeof root_element !== 'undefined' ? root_element : null);
